class Solution:
    def kthSmallestEven(self, nums, queries):
        res = []
        for l, r, k in queries:
            rem = [v for v in nums[l:r+1] if v % 2 == 0]
            cand, p, rank = 2, 0, 0
            while True:
                while p < len(rem) and rem[p] == cand:
                    cand += 2
                    p += 1
                rank += 1
                if rank == k:
                    res.append(cand)
                    break
                cand += 2
        return res

