class Solution {
public:
    vector<long long> kthSmallestEven(vector<int>& nums, vector<vector<int>>& queries) {
        vector<long long> res;
        for (auto& q : queries) {
            int l = q[0], r = q[1]; long long k = q[2];
            vector<long long> rem;
            for (int i = l; i <= r; i++)
                if (nums[i] % 2 == 0) rem.push_back(nums[i]);
            long long cand = 2, rank = 0;
            size_t p = 0;
            while (true) {
                while (p < rem.size() && rem[p] == cand) { cand += 2; p++; }
                if (++rank == k) { res.push_back(cand); break; }
                cand += 2;
            }
        }
        return res;
    }
};

