from bisect import bisect_right, bisect_left

class Solution:
    def kthSmallestEven(self, nums, queries):
        EV = [v for v in nums if v % 2 == 0]
        EI = [i for i, v in enumerate(nums) if v % 2 == 0]

        def count(l, r, x):
            j = bisect_right(EV, x)
            lo = bisect_left(EI, l, 0, j)
            hi = bisect_right(EI, r, 0, j)
            return hi - lo

        res = []
        for l, r, k in queries:
            lo, hi = 2, 2 * (k + len(EV))
            while lo < hi:
                mid = ((lo + hi) // 4) * 2
                if mid // 2 - count(l, r, mid) >= k:
                    hi = mid
                else:
                    lo = mid + 2
            res.append(lo)
        return res

