class Solution {
public:
    vector<long long> kthSmallestEven(vector<int>& nums, vector<vector<int>>& queries) {
        vector<long long> EV;
        vector<int> EI;
        for (int i = 0; i < (int)nums.size(); i++)
            if (nums[i] % 2 == 0) { EV.push_back(nums[i]); EI.push_back(i); }
        auto count = [&](int l, int r, long long x) -> long long {
            int j = upper_bound(EV.begin(), EV.end(), x) - EV.begin();
            int lo = lower_bound(EI.begin(), EI.begin() + j, l) - EI.begin();
            int hi = upper_bound(EI.begin(), EI.begin() + j, r) - EI.begin();
            return hi - lo;
        };
        vector<long long> res;
        for (auto& q : queries) {
            long long l = q[0], r = q[1], k = q[2];
            long long lo = 2, hi = 2 * (k + (long long)EV.size());
            while (lo < hi) {
                long long mid = ((lo + hi) / 4) * 2;
                if (mid / 2 - count(l, r, mid) >= k) hi = mid;
                else lo = mid + 2;
            }
            res.push_back(lo);
        }
        return res;
    }
};

