import java.util.*;

class Solution {
    public long[] kthSmallestEven(int[] nums, int[][] queries) {
        List<Long> EV = new ArrayList<>();
        List<Integer> EI = new ArrayList<>();
        for (int i = 0; i < nums.length; i++)
            if (nums[i] % 2 == 0) { EV.add((long) nums[i]); EI.add(i); }
        long[] res = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            final int l = queries[qi][0], r = queries[qi][1];
            long k = queries[qi][2];
            long lo = 2, hi = 2L * (k + EV.size());
            while (lo < hi) {
                long mid = ((lo + hi) / 4) * 2;
                int j = upperBound(EV, mid);
                int clo = lowerBoundIdx(EI, l, j);
                int chi = upperBoundIdx(EI, r, j);
                if (mid / 2 - (chi - clo) >= k) hi = mid;
                else lo = mid + 2;
            }
            res[qi] = lo;
        }
        return res;
    }
    private int upperBound(List<Long> a, long x) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a.get(m) <= x) lo = m + 1; else hi = m; }
        return lo;
    }
    private int lowerBoundIdx(List<Integer> a, int x, int end) {
        int lo = 0, hi = end;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a.get(m) < x) lo = m + 1; else hi = m; }
        return lo;
    }
    private int upperBoundIdx(List<Integer> a, int x, int end) {
        int lo = 0, hi = end;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a.get(m) <= x) lo = m + 1; else hi = m; }
        return lo;
    }
}

