var kthSmallestEven = function(nums, queries) {
    const EV = [], EI = [];
    for (let i = 0; i < nums.length; i++)
        if (nums[i] % 2 === 0) { EV.push(nums[i]); EI.push(i); }
    const ub = (a, x, end) => {
        let lo = 0, hi = end;
        while (lo < hi) { const m = (lo + hi) >> 1; if (a[m] <= x) lo = m + 1; else hi = m; }
        return lo;
    };
    const lb = (a, x, end) => {
        let lo = 0, hi = end;
        while (lo < hi) { const m = (lo + hi) >> 1; if (a[m] < x) lo = m + 1; else hi = m; }
        return lo;
    };
    const count = (l, r, x) => {
        const j = ub(EV, x, EV.length);
        return ub(EI, r, j) - lb(EI, l, j);
    };
    const res = [];
    for (const [l, r, k] of queries) {
        let lo = 2, hi = 2 * (k + EV.length);
        while (lo < hi) {
            const mid = Math.floor((lo + hi) / 4) * 2;
            if (mid / 2 - count(l, r, mid) >= k) hi = mid;
            else lo = mid + 2;
        }
        res.push(lo);
    }
    return res;
};
